def sort_list(arr: list[int]) -> list[int]:
    """Sort a list of integers in ascending order. Must be stable."""
    # Current: bubble sort O(n^2)
    result = list(arr)
    n = len(result)
    for i in range(n):
        for j in range(0, n - i - 1):
            if result[j] > result[j + 1]:
                result[j], result[j + 1] = result[j + 1], result[j]
    return result

